def strips_by_ink(scans):
    grouped = {}
    for ink, strip, _current in scans:
        grouped.setdefault(ink, set()).add(strip)
    return grouped

def currents_by_ink(scans):
    grouped = {}
    for ink, _strip, current in scans:
        grouped.setdefault(ink, []).append(current)
    return grouped
